  name: string;
  primaryColor: string;
  capacity: number;
}

export interface Team {
  id: string;
  name: string;
  playerName: string;
  isHuman: boolean;
  color: string;
  stadium: Stadium;
  initialBudget: number;
}

export interface Match {
  id: string;
  homeId: string;
  awayId: string;
  homeScore: number | null;
  awayScore: number | null;
  homeEarnings: number;
  awayEarnings: number;
  round: number;
}

export interface StandingRow {
  teamId: string;
  teamName: string;
  isHuman: boolean;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  gf: number;
  ga: number;
  gd: number;
  points: number;
  currentBudget: number;
  lastFive: ('W' | 'D' | 'L' | '-')[];
}

export type AppState = 'setup' | 'league';
export type ActiveTab = 'table' | 'matches' | 'stadiums';

import React, { useState } from 'react';
import { Team } from '../types';
import { DEFAULT_BOT_NAMES, TEAM_COLORS, TOTAL_TEAMS } from '../constants';

interface Props {
  onStart: (teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onStart }) => {
  const [numHumans, setNumHumans] = useState(1);
  const [globalBudget, setGlobalBudget] = useState(1000000);
  const [humanInputs, setHumanInputs] = useState(
    Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
      playerName: `Jogador ${i + 1}`,
      teamName: `Time ${i + 1}`,
      stadiumName: `Arena ${i + 1}`,
      capacity: 40000,
      customBudget: 1000000
    }))
  );

  const handleStart = () => {
    const finalTeams: Team[] = [];
    const availableBots = [...DEFAULT_BOT_NAMES].sort(() => Math.random() - 0.5);

    for (let i = 0; i < TOTAL_TEAMS; i++) {
      if (i < numHumans) {
        finalTeams.push({
          id: `team-${i}`,
          name: humanInputs[i].teamName,
          playerName: humanInputs[i].playerName,
          isHuman: true,
          color: TEAM_COLORS[i % TEAM_COLORS.length],
          stadium: {
            name: humanInputs[i].stadiumName,
            primaryColor: TEAM_COLORS[i % TEAM_COLORS.length],
            capacity: humanInputs[i].capacity
          },
          initialBudget: humanInputs[i].customBudget || globalBudget
        });
      } else {
        const botColor = TEAM_COLORS[(i + 3) % TEAM_COLORS.length];
        finalTeams.push({
          id: `team-${i}`,
          name: availableBots[i - numHumans] || `AI Team ${i}`,
          playerName: 'Computador',
          isHuman: false,
          color: botColor,
          stadium: {
            name: `Estádio Municipal de ${availableBots[i - numHumans]}`,
            primaryColor: botColor,
            capacity: 35000 + Math.floor(Math.random() * 20000)
          },
          initialBudget: globalBudget
        });
      }
    }
    onStart(finalTeams);
  };

  return (
    <div className="max-w-4xl mx-auto bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700 animate-in fade-in zoom-in duration-500">
      <div className="text-center mb-10">
        <h2 className="text-4xl font-black text-white tracking-tighter mb-2">BRASILEIRÃO MANAGER</h2>
        <p className="text-slate-400 font-medium">Configure sua liga de 6 times com sistema financeiro</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-700">
          <label className="block text-slate-400 text-sm font-bold mb-4 text-center uppercase tracking-widest">Técnicos Humanos</label>
          <div className="grid grid-cols-6 gap-2">
            {[1, 2, 3, 4, 5, 6].map(num => (
              <button
                key={num}
                onClick={() => setNumHumans(num)}
                className={`py-3 rounded-lg font-bold border-2 transition-all ${
                  numHumans === num 
                    ? 'bg-blue-600 border-blue-400 text-white' 
                    : 'bg-slate-900 border-slate-700 text-slate-500 hover:bg-slate-700'
                }`}
              >
                {num}
              </button>
            ))}
          </div>
        </div>

        <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-700">
          <label className="block text-slate-400 text-sm font-bold mb-2 text-center uppercase tracking-widest">Orçamento Inicial (R$)</label>
          <input 
            type="number"
            value={globalBudget}
            onChange={(e) => setGlobalBudget(parseInt(e.target.value) || 0)}
            className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-emerald-400 font-black text-xl text-center focus:ring-2 focus:ring-emerald-500 outline-none"
          />
          <p className="text-[10px] text-slate-500 text-center mt-2 uppercase font-bold">Valor aplicado a todos os times inicialmente</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
        {Array.from({ length: numHumans }).map((_, i) => (
          <div key={i} className="p-5 bg-slate-900 rounded-xl border border-slate-700 space-y-4">
            <h3 className="text-blue-400 font-bold text-xs uppercase tracking-widest flex justify-between">
              Treinador {i+1}
              <span className="text-emerald-500">HUMANO</span>
            </h3>
            <div className="space-y-3">
              <div>
                <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Identidade</label>
                <div className="flex gap-2">
                  <input
                    placeholder="Seu Nome"
                    value={humanInputs[i].playerName}
                    onChange={(e) => {
                      const newInputs = [...humanInputs];
                      newInputs[i].playerName = e.target.value;
                      setHumanInputs(newInputs);
                    }}
                    className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                  />
                  <input
                    placeholder="Nome do Clube"
                    value={humanInputs[i].teamName}
                    onChange={(e) => {
                      const newInputs = [...humanInputs];
                      newInputs[i].teamName = e.target.value;
                      setHumanInputs(newInputs);
                    }}
                    className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Orçamento do Time (R$)</label>
                <input
                  type="number"
                  value={humanInputs[i].customBudget}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].customBudget = parseInt(e.target.value) || 0;
                    setHumanInputs(newInputs);
                  }}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-3 py-2 text-emerald-400 text-sm font-bold focus:ring-1 focus:ring-emerald-500 outline-none"
                />
              </div>
            </div>
          </div>
        ))}
        {Array.from({ length: TOTAL_TEAMS - numHumans }).map((_, i) => (
          <div key={`ai-${i}`} className="p-5 bg-slate-900/30 rounded-xl border border-slate-800/50 space-y-2 opacity-60">
             <h3 className="text-slate-500 font-bold text-xs uppercase tracking-widest flex justify-between">
              Time {numHumans + i + 1}
              <span>COMPUTADOR</span>
            </h3>
            <p className="text-xs text-slate-600">Configuração automática baseada no padrão da liga.</p>
          </div>
        ))}
      </div>

      <button
        onClick={handleStart}
        className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-black py-5 rounded-xl transition-all shadow-xl shadow-emerald-500/20 uppercase tracking-widest active:scale-95 text-lg"
      >
        Começar Campeonato
      </button>
    </div>
  );
};

export default SetupForm;

import React, { useState } from 'react';
import { Match, Team } from '../types';

interface Props {
  matches: Match[];
  teams: Team[];
  onUpdateScore: (matchId: string, homeScore: number, awayScore: number) => void;
  onUpdateEarnings: (matchId: string, homeEarnings: number, awayEarnings: number) => void;
}

const MatchList: React.FC<Props> = ({ matches, teams, onUpdateScore, onUpdateEarnings }) => {
  const [selectedRound, setSelectedRound] = useState(1);
  const totalRounds = Math.max(...matches.map(m => m.round), 1);

  const filteredMatches = matches.filter(m => m.round === selectedRound);

  const getTeam = (id: string) => teams.find(t => t.id === id);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-700 overflow-x-auto custom-scrollbar gap-2">
        <div className="flex gap-2">
          {Array.from({ length: totalRounds }, (_, i) => i + 1).map(round => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              className={`px-4 py-2 rounded-lg font-bold text-sm transition-all min-w-[60px] ${
                selectedRound === round 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
                  : 'bg-slate-700 text-slate-400 hover:bg-slate-600 hover:text-white'
              }`}
            >
              R{round}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filteredMatches.map(match => {
          const home = getTeam(match.homeId);
          const away = getTeam(match.awayId);

          return (
            <div key={match.id} className="bg-slate-800 border border-slate-700 p-6 rounded-2xl shadow-xl flex flex-col gap-4 hover:border-blue-500/30 transition-all group animate-in fade-in slide-in-from-bottom-2">
              <div className="flex items-center justify-between gap-2">
                <div className="flex-1 text-right">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{home?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{home?.isHuman ? `👤 ${home.playerName}` : '🤖 AI'}</div>
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min="0"
                    value={match.homeScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, parseInt(e.target.value) || 0, match.awayScore ?? 0)}
                    placeholder="0"
                    className="w-12 h-12 md:w-14 md:h-14 bg-slate-900 border border-slate-700 rounded-xl text-center font-black text-xl md:text-2xl focus:ring-2 focus:ring-blue-500 outline-none text-white transition-all"
                  />
                  <span className="text-slate-600 font-black text-lg">X</span>
                  <input
                    type="number"
                    min="0"
                    value={match.awayScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, match.homeScore ?? 0, parseInt(e.target.value) || 0)}
                    placeholder="0"
                    className="w-12 h-12 md:w-14 md:h-14 bg-slate-900 border border-slate-700 rounded-xl text-center font-black text-xl md:text-2xl focus:ring-2 focus:ring-blue-500 outline-none text-white transition-all"
                  />
                </div>

                <div className="flex-1 text-left">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{away?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{away?.isHuman ? `👤 ${away.playerName}` : '🤖 AI'}</div>
                </div>
              </div>

              <div className="pt-4 border-t border-slate-700/50 flex flex-col gap-3">
                <div className="flex items-center justify-between text-[10px] text-slate-500 font-black uppercase tracking-widest">
                  <span>Receita Adicional (Bilheteria/Prêmios)</span>
                </div>
                <div className="flex gap-4">
                  <div className="flex-1 relative">
                    <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-emerald-500 font-bold text-[10px]">R$</span>
                    <input
                      type="number"
                      value={match.homeEarnings || ''}
                      placeholder="Ganhos Casa"
                      onChange={(e) => onUpdateEarnings(match.id, parseInt(e.target.value) || 0, match.awayEarnings)}
                      className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg pl-7 pr-2 py-2 text-[11px] font-bold text-emerald-400 focus:ring-1 focus:ring-emerald-500 outline-none placeholder:text-slate-700"
                    />
                  </div>
                  <div className="flex-1 relative">
                    <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-emerald-500 font-bold text-[10px]">R$</span>
                    <input
                      type="number"
                      value={match.awayEarnings || ''}
                      placeholder="Ganhos Fora"
                      onChange={(e) => onUpdateEarnings(match.id, match.homeEarnings, parseInt(e.target.value) || 0)}
                      className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg pl-7 pr-2 py-2 text-[11px] font-bold text-emerald-400 focus:ring-1 focus:ring-emerald-500 outline-none placeholder:text-slate-700"
                    />
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {filteredMatches.length === 0 && (
        <div className="text-center py-20 text-slate-500 font-medium">
          Nenhuma partida agendada para esta rodada.
        </div>
      )}
    </div>
  );
};

