import React, { useState } from 'react';
import { Match, Team } from '../types';

interface Props {
  matches: Match[];
  teams: Team[];
  onUpdateScore: (matchId: string, homeScore: number, awayScore: number) => void;
  onShowResults: () => void;
}

const MatchList: React.FC<Props> = ({ matches, teams, onUpdateScore, onShowResults }) => {
  const [selectedRound, setSelectedRound] = useState(1);
  const totalRounds = Math.max(...matches.map(m => m.round), 1);
  const filteredMatches = matches.filter(m => m.round === selectedRound);
  const isLastRound = selectedRound === totalRounds;

  const getTeam = (id: string) => teams.find(t => t.id === id);

  const simulateAIMatches = () => {
    filteredMatches.forEach(match => {
      const home = getTeam(match.homeId);
      const away = getTeam(match.awayId);

      // Se pelo menos um dos times for IA, simula o resultado
      if (!home?.isHuman || !away?.isHuman) {
        // Lógica simples de gols: 0 a 4 com pesos para empates e vitórias magras
        const generateGols = () => {
          const r = Math.random();
          if (r < 0.3) return 0;
          if (r < 0.6) return 1;
          if (r < 0.8) return 2;
          if (r < 0.95) return 3;
          return 4;
        };

        onUpdateScore(match.id, generateGols(), generateGols());
      }
    });
  };

  const allPlayed = filteredMatches.every(m => m.homeScore !== null && m.awayScore !== null);
  const hasAIMatches = filteredMatches.some(m => !getTeam(m.homeId)?.isHuman || !getTeam(m.awayId)?.isHuman);

  return (
    <div className="space-y-6">
      {/* Seletor de Rodadas */}
      <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-700 overflow-x-auto custom-scrollbar gap-2">
        <div className="flex gap-2">
          {Array.from({ length: totalRounds }, (_, i) => i + 1).map(round => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              className={`px-4 py-2 rounded-lg font-bold text-sm transition-all min-w-[60px] ${
                selectedRound === round 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
                  : 'bg-slate-700 text-slate-400 hover:bg-slate-600 hover:text-white'
              }`}
            >
              R{round}
            </button>
          ))}
        </div>
      </div>

      {/* Botão de Simulação de IA */}
      {hasAIMatches && (
        <div className="flex justify-end">
          <button 
            onClick={simulateAIMatches}
            className="flex items-center gap-2 px-6 py-2 bg-slate-700 hover:bg-slate-600 text-white text-xs font-black rounded-xl border border-slate-600 transition-all active:scale-95"
          >
            <span>🤖</span> SIMULAR JOGOS DA IA
          </button>
        </div>
      )}

      {/* Lista de Jogos */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filteredMatches.map(match => {
          const home = getTeam(match.homeId);
          const away = getTeam(match.awayId);
          const isInteractive = home?.isHuman && away?.isHuman;

          return (
            <div 
              key={match.id} 
              className={`bg-slate-800 border p-6 rounded-2xl shadow-xl flex flex-col gap-4 transition-all group animate-in fade-in slide-in-from-bottom-2 ${
                isInteractive 
                ? 'border-blue-500/50 bg-blue-500/5' 
                : 'border-slate-700 opacity-90'
              }`}
            >
              <div className="flex items-center justify-between gap-2">
                {/* Mandante */}
                <div className="flex-1 text-right">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{home?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
                    {home?.isHuman ? `👤 ${home.playerName}` : '🤖 IA'}
                  </div>
                </div>

                {/* Placar */}
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min="0"
                    readOnly={!isInteractive}
                    value={match.homeScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, parseInt(e.target.value) || 0, match.awayScore ?? 0)}
                    placeholder="-"
                    className={`w-12 h-12 md:w-14 md:h-14 bg-slate-900 border rounded-xl text-center font-black text-xl md:text-2xl outline-none text-white transition-all ${
                      isInteractive 
                      ? 'border-blue-500 focus:ring-2 focus:ring-blue-500' 
                      : 'border-slate-700 cursor-default'
                    }`}
                  />
                  <span className="text-slate-600 font-black text-lg">X</span>
                  <input
                    type="number"
                    min="0"
                    readOnly={!isInteractive}
                    value={match.awayScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, match.homeScore ?? 0, parseInt(e.target.value) || 0)}
                    placeholder="-"
                    className={`w-12 h-12 md:w-14 md:h-14 bg-slate-900 border rounded-xl text-center font-black text-xl md:text-2xl outline-none text-white transition-all ${
                      isInteractive 
                      ? 'border-blue-500 focus:ring-2 focus:ring-blue-500' 
                      : 'border-slate-700 cursor-default'
                    }`}
                  />
                </div>

                {/* Visitante */}
                <div className="flex-1 text-left">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{away?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
                    {away?.isHuman ? `👤 ${away.playerName}` : '🤖 IA'}
                  </div>
                </div>
              </div>

              {!isInteractive && (
                <div className="text-center">
                  <span className="text-[9px] bg-slate-900 text-slate-500 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">Resultado Automático</span>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Footer da Rodada */}
      <div className="bg-slate-900/50 border border-slate-700 border-dashed rounded-3xl p-8 mt-10 flex flex-col items-center gap-6 animate-in fade-in zoom-in-95 duration-700">
        <div className="text-center">
          <h4 className="text-white font-black text-lg mb-1 uppercase tracking-tight">Fim da Rodada {selectedRound}</h4>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">
            {allPlayed ? 'Rodada completa!' : 'Preencha ou simule os jogos pendentes'}
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full max-w-sm">
          {isLastRound && allPlayed && (
            <button
              onClick={onShowResults}
              className="flex-1 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-white font-black py-4 px-6 rounded-2xl transition-all shadow-xl shadow-amber-500/20 flex items-center justify-center gap-3 animate-pulse"
            >
              <span className="text-xl">🏆</span>
              <div className="text-left">
                <p className="text-xs uppercase tracking-widest leading-none">Resultados Finais</p>
                <p className="text-[10px] text-white/50 font-bold">Ver Campeão</p>
              </div>
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

