import React, { useState } from 'react';
import { Match, Team } from '../types';

interface Props {
  matches: Match[];
  teams: Team[];
  onUpdateScore: (matchId: string, homeScore: number, awayScore: number) => void;
  onShowResults: () => void;
}

const MatchList: React.FC<Props> = ({ matches, teams, onUpdateScore, onShowResults }) => {
  const [selectedRound, setSelectedRound] = useState(1);
  const totalRounds = Math.max(...matches.map(m => m.round), 1);
  const filteredMatches = matches.filter(m => m.round === selectedRound);
  const isLastRound = selectedRound === totalRounds;

  const getTeam = (id: string) => teams.find(t => t.id === id);

  const simulateNonInteractiveMatches = () => {
    filteredMatches.forEach(match => {
      const home = getTeam(match.homeId);
      const away = getTeam(match.awayId);

      // Literal interpretation: Only Human vs Human is manual.
      // So if either side is AI, we can simulate.
      const isHumanVsHuman = home?.isHuman && away?.isHuman;

      if (!isHumanVsHuman) {
        const generateGols = () => {
          const r = Math.random();
          if (r < 0.25) return 0;
          if (r < 0.55) return 1;
          if (r < 0.80) return 2;
          if (r < 0.93) return 3;
          return 4;
        };
        onUpdateScore(match.id, generateGols(), generateGols());
      }
    });
  };

  const allPlayed = filteredMatches.every(m => m.homeScore !== null && m.awayScore !== null);
  const hasNonInteractive = filteredMatches.some(m => !getTeam(m.homeId)?.isHuman || !getTeam(m.awayId)?.isHuman);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-700 overflow-x-auto custom-scrollbar gap-2">
        <div className="flex gap-2">
          {Array.from({ length: totalRounds }, (_, i) => i + 1).map(round => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              className={`px-4 py-2 rounded-lg font-bold text-sm transition-all min-w-[60px] ${
                selectedRound === round 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
                  : 'bg-slate-700 text-slate-400 hover:bg-slate-600 hover:text-white'
              }`}
            >
              R{round}
            </button>
          ))}
        </div>
      </div>

      {hasNonInteractive && (
        <div className="flex justify-end">
          <button 
            onClick={simulateNonInteractiveMatches}
            className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black rounded-xl shadow-lg shadow-indigo-500/20 transition-all active:scale-95"
          >
            <span>🎲</span> SIMULAR RESULTADOS IA
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filteredMatches.map(match => {
          const home = getTeam(match.homeId);
          const away = getTeam(match.awayId);
          const isHumanVsHuman = home?.isHuman && away?.isHuman;

          return (
            <div 
              key={match.id} 
              className={`bg-slate-800 border p-6 rounded-2xl shadow-xl flex flex-col gap-4 transition-all group animate-in fade-in slide-in-from-bottom-2 ${
                isHumanVsHuman 
                ? 'border-blue-500/50 bg-blue-500/5 ring-1 ring-blue-500/20' 
                : 'border-slate-700'
              }`}
            >
              <div className="flex items-center justify-between gap-2">
                <div className="flex-1 text-right">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{home?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
                    {home?.isHuman ? `👤 ${home.playerName}` : '🤖 IA'}
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min="0"
                    readOnly={!isHumanVsHuman}
                    value={match.homeScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, parseInt(e.target.value) || 0, match.awayScore ?? 0)}
                    placeholder="-"
                    className={`w-12 h-12 md:w-14 md:h-14 bg-slate-900 border rounded-xl text-center font-black text-xl md:text-2xl outline-none text-white transition-all ${
                      isHumanVsHuman 
                      ? 'border-blue-500 focus:ring-2 focus:ring-blue-500' 
                      : 'border-slate-700 cursor-default focus:border-slate-500'
                    }`}
                  />
                  <span className="text-slate-600 font-black text-lg">X</span>
                  <input
                    type="number"
                    min="0"
                    readOnly={!isHumanVsHuman}
                    value={match.awayScore ?? ''}
                    onChange={(e) => onUpdateScore(match.id, match.homeScore ?? 0, parseInt(e.target.value) || 0)}
                    placeholder="-"
                    className={`w-12 h-12 md:w-14 md:h-14 bg-slate-900 border rounded-xl text-center font-black text-xl md:text-2xl outline-none text-white transition-all ${
                      isHumanVsHuman 
                      ? 'border-blue-500 focus:ring-2 focus:ring-blue-500' 
                      : 'border-slate-700 cursor-default focus:border-slate-500'
                    }`}
                  />
                </div>

                <div className="flex-1 text-left">
                  <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate text-sm md:text-base">{away?.name}</div>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
                    {away?.isHuman ? `👤 ${away.playerName}` : '🤖 IA'}
                  </div>
                </div>
              </div>

              {!isHumanVsHuman && (
                <div className="text-center">
                  <span className="text-[9px] bg-slate-900 text-slate-500 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">
                    { (home?.isHuman || away?.isHuman) ? 'Humano vs IA (Automático)' : 'IA vs IA (Simulado)' }
                  </span>
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className="bg-slate-900/50 border border-slate-700 border-dashed rounded-3xl p-8 mt-10 flex flex-col items-center gap-6 animate-in fade-in zoom-in-95 duration-700">
        <div className="text-center">
          <h4 className="text-white font-black text-lg mb-1 uppercase tracking-tight">Rodada {selectedRound}</h4>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">
            {allPlayed ? 'Rodada completa!' : 'Complete os jogos entre humanos ou simule a IA'}
          </p>
        </div>

        {isLastRound && allPlayed && (
          <button
            onClick={onShowResults}
            className="w-full max-w-sm bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-white font-black py-4 px-6 rounded-2xl transition-all shadow-xl shadow-amber-500/20 flex items-center justify-center gap-3 animate-pulse"
          >
            <span className="text-xl">🏆</span>
            <div className="text-left">
              <p className="text-xs uppercase tracking-widest leading-none">Ver Resultados Finais</p>
              <p className="text-[10px] text-white/50 font-bold">Quem levou a taça?</p>
            </div>
          </button>
        )}
      </div>
    </div>
  );
};

export default MatchList;

export interface Stadium {
  name: string;
  primaryColor: string;
  capacity: number;
}

export interface Team {
  id: string;
  name: string;
  playerName: string;
  isHuman: true; // All teams are human
  color: string;
  stadium: Stadium;
}

export interface Match {
  id: string;
  homeId: string;
  awayId: string;
  homeScore: number | null;
  awayScore: number | null;
  round: number;
}

export interface StandingRow {
  teamId: string;
  teamName: string;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  gf: number;
  ga: number;
  gd: number;
  points: number;
  lastFive: ('W' | 'D' | 'L' | '-')[];
}

export type AppState = 'home' | 'setup' | 'league';
export type ActiveTab = 'table' | 'matches' | 'stadiums';

import React, { useState, useMemo } from 'react';
import { Team, Match, StandingRow, AppState, ActiveTab } from './types';
import Home from './components/Home';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import ChampionModal from './components/ChampionModal';
import { getLeagueAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('home');
  const [activeTab, setActiveTab] = useState<ActiveTab>('table');
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showChampionModal, setShowChampionModal] = useState(false);

  const generateSchedule = (teamList: Team[]) => {
    const rounds: Match[] = [];
    const n = teamList.length;
    const teamIds = teamList.map(t => t.id);

    // Round Robin Algorithm (Circle Method)
    for (let round = 0; round < n - 1; round++) {
      for (let i = 0; i < n / 2; i++) {
        const home = teamIds[i];
        const away = teamIds[n - 1 - i];
        rounds.push({
          id: `match-${round}-${i}`,
          homeId: home,
          awayId: away,
          homeScore: null,
          awayScore: null,
          round: round + 1
        });
      }
      const last = teamIds.pop()!;
      teamIds.splice(1, 0, last);
    }

    const secondHalf = rounds.map(m => ({
      ...m,
      id: `match-ret-${m.id}`,
      homeId: m.awayId,
      awayId: m.homeId,
      round: m.round + (n - 1)
    }));

    return [...rounds, ...secondHalf];
  };

  const handleStart = (selectedTeams: Team[]) => {
    setTeams(selectedTeams);
    setMatches(generateSchedule(selectedTeams));
    setAppState('league');
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setMatches(prev => prev.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m));
  };

  const standings = useMemo(() => {
    const stats: Record<string, StandingRow> = {};
    teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id, 
        teamName: t.name, 
        played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0, 
        lastFive: []
      };
    });

    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    teams.forEach(t => resultsByTeam[t.id] = []);

    matches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const h = stats[m.homeId];
        const a = stats[m.awayId];
        if (!h || !a) return;

        h.played++; a.played++;
        h.gf += m.homeScore; h.ga += m.awayScore;
        a.gf += m.awayScore; a.ga += m.homeScore;

        if (m.homeScore > m.awayScore) {
          h.won++; h.points += 3; a.lost++;
          resultsByTeam[m.homeId].push('W'); resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          a.won++; a.points += 3; h.lost++;
          resultsByTeam[m.homeId].push('L'); resultsByTeam[m.awayId].push('W');
        } else {
          h.drawn++; a.drawn++; h.points += 1; a.points += 1;
          resultsByTeam[m.homeId].push('D'); resultsByTeam[m.awayId].push('D');
        }
        h.gd = h.gf - h.ga;
        a.gd = a.gf - a.ga;
      }
    });

    return Object.values(stats)
      .map(s => ({ ...s, lastFive: resultsByTeam[s.teamId]?.slice(-5).reverse() || [] }))
      .sort((a, b) => (b.points - a.points) || (b.won - a.won) || (b.gd - a.gd) || (b.gf - a.gf));
  }, [matches, teams]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await getLeagueAnalysis(standings, teams);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const champion = standings[0];

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setAppState('home')}>
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
              <span className="text-white font-black text-xl">B</span>
            </div>
            <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block uppercase">Brasileirão Manager</h1>
          </div>

          {appState === 'league' && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700 overflow-x-auto gap-1">
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'home' && (
          <Home onContinue={() => setAppState('setup')} />
        )}

        {appState === 'setup' && (
          <SetupForm onStart={handleStart} />
        )}

        {appState === 'league' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {activeTab === 'table' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                  <LeagueTable standings={standings} />
                </div>
                <div className="space-y-6">
                  <section className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700 shadow-xl">
                    <h3 className="text-lg font-black text-white mb-4 flex items-center gap-2">
                      <span className="w-1 h-6 bg-purple-500 rounded"></span> Narrador AI
                    </h3>
                    {analysis ? (
                      <p className="text-slate-300 text-sm italic leading-relaxed bg-slate-900/50 p-4 rounded-xl border border-slate-700 whitespace-pre-wrap">{analysis}</p>
                    ) : (
                      <p className="text-slate-500 text-sm italic">O narrador está esperando resultados para comentar!</p>
                    )}
                    <button 
                      onClick={handleAnalyze} 
                      disabled={isAnalyzing} 
                      className="w-full mt-4 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 rounded-xl text-white text-xs font-black uppercase tracking-widest hover:opacity-90 transition-all disabled:opacity-50 active:scale-95"
                    >
                      {isAnalyzing ? 'Comentando...' : 'Pedir Análise da Rodada'}
                    </button>
                  </section>
                </div>
              </div>
            )}

            {activeTab === 'matches' && (
              <MatchList 
                matches={matches} 
                teams={teams} 
                onUpdateScore={updateScore} 
                onShowResults={() => setShowChampionModal(true)}
              />
            )}

            {activeTab === 'stadiums' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {teams.map(team => (
                  <div key={team.id} className="bg-slate-800 rounded-2xl border border-slate-700 overflow-hidden shadow-xl group hover:border-blue-500/30 transition-all">
                    <div className="h-28 relative overflow-hidden bg-slate-900 flex items-center justify-center">
                       <div className="absolute inset-0 opacity-10" style={{ backgroundImage: `linear-gradient(45deg, ${team.color} 25%, transparent 25%, transparent 50%, ${team.color} 50%, ${team.color} 75%, transparent 75%, transparent)` , backgroundSize: '40px 40px'}}></div>
                       <span className="text-6xl font-black text-white/5 uppercase select-none">{team.name}</span>
                    </div>
                    <div className="p-6">
                      <h4 className="text-white font-black text-lg mb-1">{team.stadium.name}</h4>
                      <p className="text-slate-500 text-xs uppercase font-bold tracking-widest mb-4">Sede do {team.name}</p>
                      <div className="flex justify-between items-center text-sm">
                        <span className="text-slate-400">Capacidade</span>
                        <span className="text-white font-bold">{team.stadium.capacity.toLocaleString()} torcedores</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>

      {showChampionModal && champion && (
        <ChampionModal 
          champion={champion} 
          teamDetails={teams.find(t => t.id === champion.teamId)} 
          onClose={() => setShowChampionModal(false)} 
        />
      )}
    </div>
  );
};

export default App;

