          return (
            <div 
              key={match.id} 
              className="bg-slate-800 border-2 border-slate-700 p-8 rounded-[2rem] shadow-xl flex flex-col gap-6 hover:border-blue-500/30 transition-all group animate-in fade-in slide-in-from-bottom-2 duration-500"
