              <span className="text-white font-black text-xl">B</span>
            </div>
            <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block uppercase">Brasileirão Manager</h1>
          </div>

          {appState === 'league' && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700 overflow-x-auto gap-1">
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('market')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'market' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Mercado</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'home' && (
          <Home onContinue={() => setAppState('setup')} />
        )}

        {appState === 'setup' && (
          <SetupForm onStart={handleStart} />
        )}

        {appState === 'league' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {activeTab === 'table' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                  <LeagueTable standings={standings} />
                </div>
                <div className="space-y-6">
                  <section className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700 shadow-xl">
                    <h3 className="text-lg font-black text-white mb-4 flex items-center gap-2">
                      <span className="w-1 h-6 bg-purple-500 rounded"></span> Narrador AI
                    </h3>
                    {analysis ? (
                      <p className="text-slate-300 text-sm italic leading-relaxed bg-slate-900/50 p-4 rounded-xl border border-slate-700 whitespace-pre-wrap">{analysis}</p>
                    ) : (
                      <p className="text-slate-500 text-sm italic">O narrador está esperando resultados para comentar!</p>
                    )}
                    <button 
                      onClick={handleAnalyze} 
                      disabled={isAnalyzing} 
                      className="w-full mt-4 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 rounded-xl text-white text-xs font-black uppercase tracking-widest hover:opacity-90 transition-all disabled:opacity-50 active:scale-95"
                    >
                      {isAnalyzing ? 'Comentando...' : 'Pedir Análise da Rodada'}
                    </button>
                  </section>
                </div>
              </div>
            )}

            {activeTab === 'matches' && (
              <MatchList 
                matches={matches} 
                teams={teams} 
                onUpdateScore={updateScore} 
                onShowResults={() => setShowChampionModal(true)}
              />
