export default SetupForm;

import React, { useState, useMemo, useEffect } from 'react';
import { Team, Match, StandingRow, AppState, ActiveTab, Championship, TournamentType } from './types';
import Home from './components/Home';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import ChampionModal from './components/ChampionModal';
import { getLeagueAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('dashboard');
  const [championships, setChampionships] = useState<Championship[]>([]);
  const [activeChampId, setActiveChampId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ActiveTab>('table');
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showChampionModal, setShowChampionModal] = useState(false);

  // Persistência local
  useEffect(() => {
    const saved = localStorage.getItem('brasileirao_champs');
    if (saved) setChampionships(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('brasileirao_champs', JSON.stringify(championships));
  }, [championships]);

  const activeChamp = useMemo(() => 
    championships.find(c => c.id === activeChampId), 
    [championships, activeChampId]
  );

  const generateLeagueSchedule = (teamList: Team[]) => {
    const rounds: Match[] = [];
    const n = teamList.length;
    const teamIds = teamList.map(t => t.id);
    const isOdd = n % 2 !== 0;

    // Simplificado para garantir funcionamento com N times
    const effectiveIds = isOdd ? [...teamIds, 'BYE'] : teamIds;
    const numTeams = effectiveIds.length;
    const numRounds = numTeams - 1;

    for (let r = 0; r < numRounds; r++) {
      for (let i = 0; i < numTeams / 2; i++) {
        const home = effectiveIds[i];
        const away = effectiveIds[numTeams - 1 - i];
        if (home !== 'BYE' && away !== 'BYE') {
          rounds.push({
            id: `m-${r}-${i}`,
            homeId: home,
            awayId: away,
            homeScore: null,
            awayScore: null,
            round: r + 1
          });
        }
      }
      effectiveIds.splice(1, 0, effectiveIds.pop()!);
    }
    return rounds;
  };

  const generateCupSchedule = (teamList: Team[]) => {
    const matches: Match[] = [];
    const n = teamList.length;
    // Para simplificar, faremos uma eliminatória simples (mata-mata)
    // O número de times ideal é potência de 2, mas faremos a primeira fase com o que tiver
    for (let i = 0; i < n; i += 2) {
      if (i + 1 < n) {
        matches.push({
          id: `cup-m1-${i}`,
          homeId: teamList[i].id,
          awayId: teamList[i+1].id,
          homeScore: null,
          awayScore: null,
          round: 1,
          stage: 'Primeira Fase'
        });
      }
    }
    return matches;
  };

  const createChampionship = (name: string, type: TournamentType, teams: Team[]) => {
    const newChamp: Championship = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      teams,
      matches: type === 'league' ? generateLeagueSchedule(teams) : generateCupSchedule(teams),
      status: 'active',
      createdAt: Date.now()
    };
    setChampionships([newChamp, ...championships]);
    setActiveChampId(newChamp.id);
    setAppState('active_tournament');
    setActiveTab(type === 'league' ? 'table' : 'matches');
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setChampionships(prev => prev.map(c => {
      if (c.id === activeChampId) {
        return {
          ...c,
          matches: c.matches.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m)
        };
      }
      return c;
    }));
  };

  const deleteChampionship = (id: string) => {
    setChampionships(prev => prev.filter(c => c.id !== id));
    if (activeChampId === id) setAppState('dashboard');
  };

  const standings = useMemo(() => {
    if (!activeChamp || activeChamp.type !== 'league') return [];

    const stats: Record<string, StandingRow> = {};
    activeChamp.teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id, teamName: t.name, isHuman: t.isHuman,
        played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0, lastFive: []
      };
    });

    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    activeChamp.teams.forEach(t => resultsByTeam[t.id] = []);

    activeChamp.matches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const h = stats[m.homeId];
        const a = stats[m.awayId];
        if (!h || !a) return;
        h.played++; a.played++;
        h.gf += m.homeScore; h.ga += m.awayScore;
        a.gf += m.awayScore; a.ga += m.homeScore;
        if (m.homeScore > m.awayScore) {
          h.won++; h.points += 3; a.lost++;
          resultsByTeam[m.homeId].push('W'); resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          a.won++; a.points += 3; h.lost++;
          resultsByTeam[m.homeId].push('L'); resultsByTeam[m.awayId].push('W');
        } else {
          h.drawn++; a.drawn++; h.points += 1; a.points += 1;
          resultsByTeam[m.homeId].push('D'); resultsByTeam[m.awayId].push('D');
        }
        h.gd = h.gf - h.ga; a.gd = a.gf - a.ga;
      }
    });

    return Object.values(stats)
      .map(s => ({ ...s, lastFive: resultsByTeam[s.teamId]?.slice(-5).reverse() || [] }))
      .sort((a, b) => b.points - a.points || b.won - a.won || b.gd - a.gd || b.gf - a.gf);
  }, [activeChamp]);

  const handleAnalyze = async () => {
    if (!activeChamp) return;
    setIsAnalyzing(true);
    const result = await getLeagueAnalysis(activeChamp.type === 'league' ? standings : [], activeChamp.teams);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setAppState('dashboard')}>
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
              <span className="text-white font-black text-xl">B</span>
            </div>
            <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block uppercase">Manager Pro</h1>
          </div>

          {appState === 'active_tournament' && activeChamp && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700 overflow-x-auto gap-1">
              {activeChamp.type === 'league' && (
                <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              )}
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}

          <button 
            onClick={() => setAppState('create')}
            className="px-4 py-2 bg-blue-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-500 transition-all"
          >
            + Novo Torneio
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in duration-700">
            <div className="text-center space-y-4">
              <h2 className="text-5xl font-black text-white tracking-tighter uppercase italic">Seus <span className="text-blue-500">Campeonatos</span></h2>
              <p className="text-slate-400 text-lg">Gerencie todas as suas ligas e copas em um só lugar.</p>
            </div>

            {championships.length === 0 ? (
              <div className="bg-slate-800/50 border-2 border-dashed border-slate-700 rounded-[3rem] p-20 text-center space-y-6">
                <p className="text-slate-500 font-medium italic text-xl">Nenhum campeonato criado ainda...</p>
                <button onClick={() => setAppState('create')} className="px-10 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-blue-500/20">Criar Primeiro Torneio</button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {championships.map(c => (
                  <div key={c.id} className="bg-slate-800 border border-slate-700 p-8 rounded-[2.5rem] shadow-xl hover:border-blue-500/40 transition-all group relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 group-hover:bg-blue-600/10 transition-colors"></div>
                    <div className="relative z-10 flex flex-col h-full">
                      <div className="flex justify-between items-start mb-4">
                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${c.type === 'league' ? 'bg-blue-500/20 text-blue-400' : 'bg-amber-500/20 text-amber-400'}`}>
                          {c.type === 'league' ? 'Liga' : 'Copa'}
                        </span>
                        <button onClick={() => deleteChampionship(c.id)} className="text-slate-600 hover:text-rose-500 transition-colors">✕</button>
                      </div>
                      <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tighter truncate">{c.name}</h3>
                      <p className="text-slate-500 text-xs font-bold mb-6">{c.teams.length} TIMES PARTICIPANTES</p>
                      <button 
                        onClick={() => { setActiveChampId(c.id); setAppState('active_tournament'); setActiveTab(c.type === 'league' ? 'table' : 'matches'); }}
                        className="mt-auto w-full py-4 bg-slate-700 group-hover:bg-blue-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-lg"
                      >
                        Abrir Painel
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {appState === 'create' && (
          <SetupForm onCancel={() => setAppState('dashboard')} onStart={createChampionship} />
        )}

        {appState === 'active_tournament' && activeChamp && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter">{activeChamp.name}</h2>
                <p className="text-slate-500 font-bold text-xs uppercase tracking-[0.2em]">{activeChamp.type === 'league' ? 'Formato Pontos Corridos' : 'Formato Mata-Mata'}</p>
              </div>
              <button onClick={handleAnalyze} disabled={isAnalyzing} className="px-6 py-2 bg-purple-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-purple-500 transition-all shadow-lg shadow-purple-500/20">
                {isAnalyzing ? 'Analisando...' : 'Pedir Análise da IA'}
              </button>
            </div>

            {analysis && (
              <div className="bg-slate-800/80 border border-slate-700 p-6 rounded-3xl shadow-xl animate-in fade-in duration-500">
                <h4 className="text-purple-400 text-xs font-black uppercase tracking-widest mb-3 flex items-center gap-2">
                  <span className="w-1 h-4 bg-purple-500 rounded"></span> Comentário do Narrador
                </h4>
                <p className="text-slate-300 text-sm italic leading-relaxed whitespace-pre-wrap">{analysis}</p>
              </div>
            )}

            {activeTab === 'table' && activeChamp.type === 'league' && (
              <LeagueTable standings={standings} />
            )}

            {activeTab === 'matches' && (
              <MatchList 
                matches={activeChamp.matches} 
                teams={activeChamp.teams} 
                onUpdateScore={updateScore} 
                onShowResults={() => setShowChampionModal(true)}
              />
            )}

            {activeTab === 'stadiums' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {activeChamp.teams.map(team => (
                  <div key={team.id} className="bg-slate-800 rounded-3xl border border-slate-700 overflow-hidden shadow-xl hover:border-blue-500/30 transition-all">
                    <div className="h-24 bg-slate-900 flex items-center justify-center relative">
                       <div className="absolute inset-0 opacity-10" style={{ backgroundImage: `linear-gradient(45deg, ${team.color} 25%, transparent 25%, transparent 50%, ${team.color} 50%, ${team.color} 75%, transparent 75%, transparent)` , backgroundSize: '30px 30px'}}></div>
