        )}
      </main>

      {showChampionModal && activeChamp && activeChamp.type === 'league' && (
        <ChampionModal 
          champion={standings[0]} 
          teamDetails={activeChamp.teams.find(t => t.id === standings[0].teamId)} 
          onClose={() => setShowChampionModal(false)} 
        />
      )}
    </div>
  );
};

export default App;

