import { GoogleGenAI } from "@google/genai";
import React, { useState } from 'react';

interface Props {
  onImageGenerated: (base64: string) => void;
  onClose: () => void;
  defaultTeamName: string;
  defaultColor: string;
}

type ImageSize = '1K' | '2K' | '4K';

const AIImageGenerator: React.FC<Props> = ({ onImageGenerated, onClose, defaultTeamName, defaultColor }) => {
  const [prompt, setPrompt] = useState(`A professional football team crest for "${defaultTeamName}", modern style, circular shield, primary color ${defaultColor}, high quality, minimalist vector art.`);
  const [imageSize, setImageSize] = useState<ImageSize>('1K');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState('');

  const loadingMessages = [
    "Desenhando as primeiras linhas...",
    "Escolhendo as cores da glória...",
    "Refinando os detalhes do escudo...",
    "Finalizando sua obra de arte...",
    "Quase pronto para o campo!"
  ];

  const handleSelectKey = async () => {
    try {
      await window.aistudio.openSelectKey();
    } catch (err) {
      setError("Falha ao abrir seleção de chave.");
    }
  };

  const generate = async () => {
    setIsGenerating(true);
    setError(null);
    let msgIndex = 0;
    const interval = setInterval(() => {
      setLoadingMessage(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
    }, 3000);

    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await handleSelectKey();
        // Proceeding as per instructions (assuming key selection success)
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [{ text: prompt }],
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1",
            imageSize: imageSize
          }
        },
      });

      const candidate = response.candidates?.[0];
      if (!candidate) throw new Error("Nenhum resultado gerado.");

      let foundImage = false;
      for (const part of candidate.content.parts) {
        if (part.inlineData) {
          const base64Data = part.inlineData.data;
          const imageUrl = `data:${part.inlineData.mimeType};base64,${base64Data}`;
          setGeneratedImage(imageUrl);
          foundImage = true;
          break;
        }
      }

      if (!foundImage) {
        throw new Error("A IA respondeu apenas com texto. Tente refinar o prompt.");
      }
    } catch (err: any) {
      console.error("AI Generation Error:", err);
      const errorMsg = err.message || "";

      if (errorMsg.includes("403") || errorMsg.includes("permission") || errorMsg.includes("not found")) {
        setError("Permissão Negada. Selecione uma chave de API válida de um projeto faturado.");
        // Automatically prompt to re-select key if it was a permission issue
        setTimeout(() => {
          handleSelectKey();
        }, 1000);
      } else {
        setError("Ocorreu um erro ao gerar a imagem. Verifique sua conexão e chave de API.");
      }
    } finally {
      clearInterval(interval);
      setIsGenerating(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="bg-slate-900 border-2 border-slate-700 w-full max-w-2xl rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-8 border-b border-slate-800 flex justify-between items-center bg-slate-800/50">
          <div>
            <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Gerador de Brasão AI</h3>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">Powered by Gemini 3 Pro Image</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-8 overflow-y-auto space-y-6">
          {!generatedImage && !isGenerating && (
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-blue-500 uppercase tracking-widest ml-1">Descrição do Brasão</label>
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-2xl p-4 text-white text-sm outline-none focus:border-blue-500 min-h-[120px] transition-all"
                  placeholder="Descreva como você quer o brasão..."
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-blue-500 uppercase tracking-widest ml-1">Resolução (Qualidade)</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['1K', '2K', '4K'] as ImageSize[]).map((size) => (
                    <button
                      key={size}
                      onClick={() => setImageSize(size)}
                      className={`py-3 rounded-xl font-black text-xs transition-all border ${
                        imageSize === size 
                        ? 'bg-blue-600 text-white border-blue-500 shadow-lg' 
                        : 'bg-slate-950 text-slate-500 border-slate-800 hover:border-slate-600'
                      }`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="flex flex-col items-center justify-center py-12 space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-2xl">🎨</div>
              </div>
              <div className="text-center">
                <p className="text-white font-black text-xl animate-pulse">{loadingMessage}</p>
                <p className="text-slate-500 text-xs mt-2">Isso requer uma chave de API paga e faturada.</p>
              </div>
            </div>
          )}

          {generatedImage && !isGenerating && (
            <div className="space-y-6 animate-in zoom-in duration-300">
              <div className="bg-slate-950 rounded-3xl p-4 border border-slate-700 flex justify-center shadow-inner">
                <img src={generatedImage} className="max-w-full max-h-[300px] rounded-2xl shadow-2xl" alt="Generated crest" />
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => setGeneratedImage(null)} 
                  className="flex-1 py-4 bg-slate-800 text-white font-black rounded-2xl uppercase tracking-widest text-xs hover:bg-slate-700 transition-all"
                >
                  Tentar Outro
                </button>
                <button 
                  onClick={() => { onImageGenerated(generatedImage); onClose(); }} 
                  className="flex-[2] py-4 bg-emerald-600 text-white font-black rounded-2xl uppercase tracking-widest text-xs hover:bg-emerald-500 transition-all shadow-lg shadow-emerald-500/20"
                >
                  Usar Este Brasão
                </button>
              </div>
            </div>
          )}

          {error && (
            <div className="bg-rose-500/10 border border-rose-500/30 p-4 rounded-2xl space-y-3">
              <p className="text-rose-500 text-xs font-bold text-center">{error}</p>
              <button 
                onClick={handleSelectKey}
                className="w-full py-2 bg-rose-500 text-white text-[10px] font-black uppercase rounded-lg hover:bg-rose-600 transition-colors"
              >
                Selecionar Outra Chave
              </button>
            </div>
          )}
        </div>

        {!generatedImage && !isGenerating && (
          <div className="p-8 bg-slate-800/30 border-t border-slate-800">
            <button 
              onClick={generate}
              className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-2xl uppercase tracking-[0.2em] transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-3"
            >
              ✨ Gerar com IA
            </button>
            <p className="text-center text-[9px] text-slate-600 mt-4 font-bold">
              <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="underline hover:text-blue-400">Clique aqui para ver a documentação de faturamento</a>.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

