import { GoogleGenAI } from "@google/genai";
import React, { useState } from 'react';

interface Props {
  onImageGenerated: (base64: string) => void;
  onClose: () => void;
  defaultTeamName: string;
  defaultColor: string;
}

type ImageSize = '1K' | '2K' | '4K';

const AIImageGenerator: React.FC<Props> = ({ onImageGenerated, onClose, defaultTeamName, defaultColor }) => {
  const [prompt, setPrompt] = useState(`A professional football team crest for "${defaultTeamName}", modern style, circular shield, primary color ${defaultColor}, high quality, minimalist vector art.`);
  const [imageSize, setImageSize] = useState<ImageSize>('1K');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState('');

  const loadingMessages = [
    "Desenhando as primeiras linhas...",
    "Escolhendo as cores da glória...",
    "Refinando os detalhes do escudo...",
    "Finalizando sua obra de arte...",
    "Quase pronto para o campo!"
  ];

  const handleSelectKey = async () => {
    try {
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      setError("Falha ao abrir seleção de chave.");
    }
  };

  const generate = async () => {
    setIsGenerating(true);
    setError(null);
    let msgIndex = 0;
    const interval = setInterval(() => {
      setLoadingMessage(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
    }, 3000);

    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await handleSelectKey();
        // Continue after triggering key selection
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [{ text: prompt }],
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1",
            imageSize: imageSize
          }
        },
      });

      const candidate = response.candidates?.[0];
      if (!candidate) throw new Error("Nenhum resultado gerado.");

      let foundImage = false;
      for (const part of candidate.content.parts) {
        if (part.inlineData) {
          const base64Data = part.inlineData.data;
          const imageUrl = `data:${part.inlineData.mimeType};base64,${base64Data}`;
          setGeneratedImage(imageUrl);
          foundImage = true;
          break;
        }
      }

      if (!foundImage) {
        throw new Error("A IA respondeu apenas com texto. Tente refinar o prompt.");
      }
    } catch (err: any) {
      console.error("AI Generation Error:", err);
      const errorMsg = err.message || JSON.stringify(err);

      if (errorMsg.includes("403") || errorMsg.includes("PERMISSION_DENIED") || errorMsg.includes("permission") || errorMsg.includes("not found")) {
        setError("Erro de Permissão (403): Este modelo requer uma API Key de um projeto com faturamento ativado (Paid Project).");
        // Reset key selection state as per instructions if entity not found or permission denied
        await window.aistudio.openSelectKey();
      } else {
        setError("Ocorreu um erro ao gerar a imagem. Verifique sua conexão e chave de API.");
      }
    } finally {
      clearInterval(interval);
      setIsGenerating(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="bg-slate-900 border-2 border-slate-700 w-full max-w-2xl rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-8 border-b border-slate-800 flex justify-between items-center bg-slate-800/50">
          <div>
            <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Gerador de Brasão AI</h3>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">Powered by Gemini 3 Pro Image</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-8 overflow-y-auto space-y-6">
          {!generatedImage && !isGenerating && (
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-blue-500 uppercase tracking-widest ml-1">Descrição do Brasão</label>
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-2xl p-4 text-white text-sm outline-none focus:border-blue-500 min-h-[120px] transition-all"
                  placeholder="Descreva como você quer o brasão..."
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-blue-500 uppercase tracking-widest ml-1">Resolução (Qualidade)</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['1K', '2K', '4K'] as ImageSize[]).map((size) => (
                    <button
                      key={size}
                      onClick={() => setImageSize(size)}
                      className={`py-3 rounded-xl font-black text-xs transition-all border ${
                        imageSize === size 
                        ? 'bg-blue-600 text-white border-blue-500 shadow-lg' 
                        : 'bg-slate-950 text-slate-500 border-slate-800 hover:border-slate-600'
                      }`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="flex flex-col items-center justify-center py-12 space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-2xl">🎨</div>
              </div>
              <div className="text-center">
                <p className="text-white font-black text-xl animate-pulse">{loadingMessage}</p>
                <p className="text-slate-500 text-xs mt-2">Isso requer uma chave de API paga e faturada.</p>
              </div>
            </div>
          )}

          {generatedImage && !isGenerating && (
            <div className="space-y-6 animate-in zoom-in duration-300">
              <div className="bg-slate-950 rounded-3xl p-4 border border-slate-700 flex justify-center shadow-inner">
                <img src={generatedImage} className="max-w-full max-h-[300px] rounded-2xl shadow-2xl" alt="Generated crest" />
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => setGeneratedImage(null)} 
                  className="flex-1 py-4 bg-slate-800 text-white font-black rounded-2xl uppercase tracking-widest text-xs hover:bg-slate-700 transition-all"
                >
                  Tentar Outro
                </button>
                <button 
                  onClick={() => { onImageGenerated(generatedImage); onClose(); }} 
                  className="flex-[2] py-4 bg-emerald-600 text-white font-black rounded-2xl uppercase tracking-widest text-xs hover:bg-emerald-500 transition-all shadow-lg shadow-emerald-500/20"
                >
                  Usar Este Brasão
                </button>
              </div>
            </div>
          )}

          {error && (
            <div className="bg-rose-500/10 border border-rose-500/30 p-4 rounded-2xl space-y-3">
              <p className="text-rose-500 text-xs font-bold text-center whitespace-pre-wrap">{error}</p>
              <div className="flex flex-col gap-2">
                <button 
                  onClick={handleSelectKey}
                  className="w-full py-2 bg-rose-500 text-white text-[10px] font-black uppercase rounded-lg hover:bg-rose-600 transition-colors"
                >
                  Trocar API Key
                </button>
                <a 
                  href="https://ai.google.dev/gemini-api/docs/billing" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="text-[10px] text-center text-blue-400 hover:underline font-bold"
                >
                  Saiba mais sobre o faturamento da API
                </a>
              </div>
            </div>
          )}
        </div>

        {!generatedImage && !isGenerating && (
          <div className="p-8 bg-slate-800/30 border-t border-slate-800">
            <button 
              onClick={generate}
              className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-2xl uppercase tracking-[0.2em] transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-3"
            >
              ✨ Gerar com IA
            </button>
            <p className="text-center text-[9px] text-slate-600 mt-4 font-bold">
              Uso do Gemini 3 Pro Image requer faturamento habilitado.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default AIImageGenerator;

import React, { useState, useEffect } from 'react';
import { Team, TournamentType, SavedTeam } from '../types';
import { TEAM_COLORS, TOTAL_TEAMS } from '../constants';
import CrestPicker from './CrestPicker';
import AIImageGenerator from './AIImageGenerator';

interface Props {
  onCancel: () => void;
  onStart: (name: string, type: TournamentType, teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onCancel, onStart }) => {
  const [tournamentName, setTournamentName] = useState('Super League');
  const [type, setType] = useState<TournamentType>('league');
  const [savedTeams, setSavedTeams] = useState<SavedTeam[]>([]);
  const [activePickerTeamId, setActivePickerTeamId] = useState<string | null>(null);
  const [activeGeneratorTeamId, setActiveGeneratorTeamId] = useState<string | null>(null);

  const [teams, setTeams] = useState<Partial<Team>[]>(Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
    id: Math.random().toString(36).substr(2, 9),
    name: `Clube ${i + 1}`,
    playerName: `Treinador ${i + 1}`,
    color: TEAM_COLORS[i % TEAM_COLORS.length],
    stadium: { name: `Arena ${i + 1}`, primaryColor: TEAM_COLORS[i % TEAM_COLORS.length], capacity: 40000 + (i * 2000) }
  })));

  useEffect(() => {
    const saved = localStorage.getItem('manager_saved_teams_vault');
    if (saved) {
      try {
        setSavedTeams(JSON.parse(saved));
      } catch (e) {
        console.error("Erro ao carregar times salvos");
      }
    }
  }, []);

  const handleLogoUpload = (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      updateTeam(id, 'logoUrl', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const saveTeamToVault = (team: Partial<Team>) => {
    const newSaved: SavedTeam = {
      id: team.id || Math.random().toString(36).substr(2, 9),
      name: team.name || 'Sem Nome',
      playerName: team.playerName || 'Sem Treinador',
      stadiumName: team.stadium?.name || 'Estádio',
      color: team.color || '#3b82f6',
      logoUrl: team.logoUrl
    };

    const updated = [newSaved, ...savedTeams.filter(t => t.name !== newSaved.name)].slice(0, 20);
    setSavedTeams(updated);
    localStorage.setItem('manager_saved_teams_vault', JSON.stringify(updated));
    alert(`${team.name} salvo para torneios futuros!`);
  };

  const loadSavedTeam = (targetId: string, saved: SavedTeam) => {
    setTeams(teams.map(t => {
      if (t.id === targetId) {
        return {
          ...t,
          name: saved.name,
          playerName: saved.playerName,
          color: saved.color,
          logoUrl: saved.logoUrl,
          stadium: { ...t.stadium!, name: saved.stadiumName, primaryColor: saved.color }
        };
      }
      return t;
    }));
  };

  const updateTeam = (id: string, field: string, value: any) => {
    setTeams(teams.map(t => {
      if (t.id === id) {
        if (field.includes('.')) {
          const [parent, child] = field.split('.');
          return { ...t, [parent]: { ...(t as any)[parent], [child]: value } };
        }
        return { ...t, [field]: value };
      }
      return t;
    }));
  };

  const handleStart = () => {
    if (!tournamentName.trim()) return alert("Dê um nome ao torneio!");

    const finalTeams: Team[] = teams.map((t, i) => ({
      ...t,
      isHuman: true,
      color: t.color || TEAM_COLORS[i % TEAM_COLORS.length],
      players: [],
      budget: 10000000,
      sponsorship: 500000,
      salaries: 200000
    } as Team));

    onStart(tournamentName, type, finalTeams);
  };

  const activeGenTeam = teams.find(t => t.id === activeGeneratorTeamId || t.id === activePickerTeamId);

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-20 animate-in fade-in zoom-in duration-500">
      <div className="bg-slate-800 p-8 rounded-[3rem] border border-slate-700 shadow-2xl">
        <div className="flex flex-col lg:flex-row justify-between items-center gap-8 mb-10 pb-10 border-b border-slate-700/50">
          <div className="flex-1 space-y-2 w-full">
            <label className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] ml-2">Título da Competição</label>
            <input 
              value={tournamentName} 
              onChange={e => setTournamentName(e.target.value)} 
              className="w-full bg-slate-900 border-2 border-slate-700 rounded-[2rem] px-8 py-5 text-3xl font-black text-white outline-none focus:border-blue-500 transition-all shadow-inner" 
            />
          </div>
          <div className="flex bg-slate-900 p-2 rounded-[2rem] border-2 border-slate-700 shadow-lg">
            <button 
              onClick={() => setType('league')} 
              className={`px-10 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${type === 'league' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'}`}
            >
              📊 Pontos Corridos
            </button>
            <button 
              onClick={() => setType('cup')} 
              className={`px-10 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${type === 'cup' ? 'bg-amber-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'}`}
            >
              🏆 Mata-Mata
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {teams.map((team) => (
            <div key={team.id} className="bg-slate-900/40 p-6 rounded-[2.5rem] border border-slate-700 flex flex-col gap-5 group hover:border-blue-500/30 transition-all">
              <div className="flex items-center gap-4">
                <div className="relative group/logo">
                  <div 
                    className="w-20 h-20 rounded-2xl flex items-center justify-center text-3xl font-black text-white shadow-lg overflow-hidden border-2 border-slate-700 transition-colors"
                    style={{ backgroundColor: team.color }}
                  >
                    {team.logoUrl ? (
                      team.logoUrl.length > 5 ? <img src={team.logoUrl} className="w-full h-full object-cover" alt="Logo" /> : team.logoUrl
                    ) : (
                      team.name?.[0] || '?'
                    )}
                  </div>
                  <div className="absolute inset-0 flex flex-col gap-1 items-center justify-center bg-black/70 opacity-0 group-hover/logo:opacity-100 transition-opacity rounded-2xl">
                    <label className="text-[9px] font-black text-white uppercase cursor-pointer hover:text-blue-400">
                      Upload
                      <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && handleLogoUpload(team.id!, e.target.files[0])} />
                    </label>
                    <button 
                      onClick={() => setActivePickerTeamId(team.id!)}
                      className="text-[9px] font-black text-white uppercase hover:text-blue-400"
                    >
                      Emoji
                    </button>
                    <button 
                      onClick={() => setActiveGeneratorTeamId(team.id!)}
                      className="text-[9px] font-black text-emerald-400 uppercase hover:text-emerald-300"
                    >
                      IA
                    </button>
                  </div>
                </div>
                <div className="flex-1">
                  <input 
                    placeholder="Nome do Clube" 
                    value={team.name} 
                    onChange={e => updateTeam(team.id!, 'name', e.target.value)} 
                    className="bg-transparent text-xl font-black text-white outline-none w-full border-b border-transparent focus:border-blue-500 mb-1"
                  />
                  <div className="flex gap-2">
                    <input type="color" value={team.color} onChange={e => updateTeam(team.id!, 'color', e.target.value)} className="w-6 h-6 rounded cursor-pointer bg-transparent border-none" />
                    <button onClick={() => saveTeamToVault(team)} className="text-[8px] font-black text-blue-400 uppercase tracking-widest hover:text-blue-300">Salvar</button>
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700/50">
                  <label className="text-[8px] text-slate-500 font-black uppercase mb-1 block">Técnico</label>
                  <input value={team.playerName} onChange={e => updateTeam(team.id!, 'playerName', e.target.value)} className="bg-transparent text-white font-bold w-full outline-none text-sm" />
                </div>
                <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700/50">
                  <label className="text-[8px] text-slate-500 font-black uppercase mb-1 block">Estádio</label>
                  <input value={team.stadium?.name} onChange={e => updateTeam(team.id!, 'stadium.name', e.target.value)} className="bg-transparent text-white font-bold w-full outline-none text-sm" />
                </div>
              </div>

              {savedTeams.length > 0 && (
                <div className="mt-2">
                  <select 
                    onChange={(e) => {
                      const saved = savedTeams.find(st => st.id === e.target.value);
                      if (saved) loadSavedTeam(team.id!, saved);
                    }}
                    className="w-full bg-slate-800 text-slate-400 text-[10px] font-bold p-2 rounded-lg border border-slate-700 outline-none"
                  >
                    <option value="">Carregar Time Salvo...</option>
                    {savedTeams.map(st => <option key={st.id} value={st.id}>{st.name}</option>)}
                  </select>
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="flex flex-col sm:flex-row gap-4 mt-12">
          <button onClick={onCancel} className="flex-1 py-6 bg-slate-700 hover:bg-slate-600 text-white font-black rounded-[2rem] uppercase tracking-widest transition-all text-sm">Voltar</button>
          <button onClick={handleStart} className="flex-[2] py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-[2rem] uppercase tracking-widest transition-all text-sm shadow-2xl shadow-blue-500/20">Iniciar Temporada</button>
        </div>
      </div>

      {activePickerTeamId && activeGenTeam && (
        <CrestPicker
          onClose={() => setActivePickerTeamId(null)}
          onSelect={(symbol) => updateTeam(activePickerTeamId, 'logoUrl', symbol)}
          teamColor={activeGenTeam.color || '#3b82f6'}
        />
      )}

      {activeGeneratorTeamId && activeGenTeam && (
        <AIImageGenerator
          onClose={() => setActiveGeneratorTeamId(null)}
          onImageGenerated={(base64) => updateTeam(activeGeneratorTeamId, 'logoUrl', base64)}
          defaultTeamName={activeGenTeam.name || ''}
          defaultColor={activeGenTeam.color || '#3b82f6'}
        />
      )}
    </div>
  );
};

