import React, { useState, useEffect } from 'react';
import { Team, TournamentType, SavedTeam } from '../types';
import { TEAM_COLORS, TOTAL_TEAMS } from '../constants';
import CrestPicker from './CrestPicker';
import AIImageGenerator from './AIImageGenerator';

interface Props {
  onCancel: () => void;
  onStart: (name: string, type: TournamentType, teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onCancel, onStart }) => {
  const [tournamentName, setTournamentName] = useState('Super League');
  const [type, setType] = useState<TournamentType>('league');
  const [savedTeams, setSavedTeams] = useState<SavedTeam[]>([]);
  const [activePickerTeamId, setActivePickerTeamId] = useState<string | null>(null);
  const [activeGeneratorTeamId, setActiveGeneratorTeamId] = useState<string | null>(null);

  const [teams, setTeams] = useState<Partial<Team>[]>(Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
    id: Math.random().toString(36).substr(2, 9),
    name: `Clube ${i + 1}`,
    playerName: `Treinador ${i + 1}`,
    color: TEAM_COLORS[i % TEAM_COLORS.length],
    stadium: { name: `Arena ${i + 1}`, primaryColor: TEAM_COLORS[i % TEAM_COLORS.length], capacity: 40000 + (i * 2000) }
  })));

  useEffect(() => {
    const saved = localStorage.getItem('manager_saved_teams_vault');
    if (saved) {
      try {
        setSavedTeams(JSON.parse(saved));
      } catch (e) {
        console.error("Erro ao carregar times salvos");
      }
    }
  }, []);

  const handleLogoUpload = (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      updateTeam(id, 'logoUrl', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const saveTeamToVault = (team: Partial<Team>) => {
    const newSaved: SavedTeam = {
      id: team.id || Math.random().toString(36).substr(2, 9),
      name: team.name || 'Sem Nome',
      playerName: team.playerName || 'Sem Treinador',
      stadiumName: team.stadium?.name || 'Estádio',
      color: team.color || '#3b82f6',
      logoUrl: team.logoUrl
    };

    const updated = [newSaved, ...savedTeams.filter(t => t.name !== newSaved.name)].slice(0, 20);
    setSavedTeams(updated);
    localStorage.setItem('manager_saved_teams_vault', JSON.stringify(updated));
    alert(`${team.name} salvo para torneios futuros!`);
  };

  const loadSavedTeam = (targetId: string, saved: SavedTeam) => {
    setTeams(teams.map(t => {
      if (t.id === targetId) {
        return {
          ...t,
          name: saved.name,
          playerName: saved.playerName,
          color: saved.color,
          logoUrl: saved.logoUrl,
          stadium: { ...t.stadium!, name: saved.stadiumName, primaryColor: saved.color }
        };
      }
      return t;
    }));
  };

  const updateTeam = (id: string, field: string, value: any) => {
    setTeams(teams.map(t => {
      if (t.id === id) {
        if (field.includes('.')) {
          const [parent, child] = field.split('.');
          return { ...t, [parent]: { ...(t as any)[parent], [child]: value } };
        }
        return { ...t, [field]: value };
      }
      return t;
    }));
  };

  const handleStart = () => {
    if (!tournamentName.trim()) return alert("Dê um nome ao torneio!");

    const finalTeams: Team[] = teams.map((t, i) => ({
      ...t,
      isHuman: true,
      color: t.color || TEAM_COLORS[i % TEAM_COLORS.length],
      players: [],
      budget: 10000000,
      sponsorship: 500000,
      salaries: 200000
    } as Team));

    onStart(tournamentName, type, finalTeams);
  };

  const activeGenTeam = teams.find(t => t.id === activeGeneratorTeamId || t.id === activePickerTeamId);

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-20 animate-in fade-in zoom-in duration-500">
      <div className="bg-slate-800 p-8 rounded-[3rem] border border-slate-700 shadow-2xl">
        <div className="flex flex-col lg:flex-row justify-between items-center gap-8 mb-10 pb-10 border-b border-slate-700/50">
          <div className="flex-1 space-y-2 w-full">
            <label className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] ml-2">Título da Competição</label>
            <input 
              value={tournamentName} 
              onChange={e => setTournamentName(e.target.value)} 
              className="w-full bg-slate-900 border-2 border-slate-700 rounded-[2rem] px-8 py-5 text-3xl font-black text-white outline-none focus:border-blue-500 transition-all shadow-inner" 
            />
          </div>
          <div className="flex bg-slate-900 p-2 rounded-[2rem] border-2 border-slate-700 shadow-lg">
            <button 
              onClick={() => setType('league')} 
              className={`px-10 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${type === 'league' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'}`}
            >
              📊 Pontos Corridos
            </button>
            <button 
              onClick={() => setType('cup')} 
              className={`px-10 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${type === 'cup' ? 'bg-amber-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'}`}
            >
              🏆 Mata-Mata
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {teams.map((team) => (
            <div key={team.id} className="bg-slate-900/40 p-6 rounded-[2.5rem] border border-slate-700 flex flex-col gap-5 group hover:border-blue-500/30 transition-all">
              <div className="flex items-center gap-4">
                <div className="relative group/logo">
                  <div 
                    className="w-20 h-20 rounded-2xl flex items-center justify-center text-3xl font-black text-white shadow-lg overflow-hidden border-2 border-slate-700 transition-colors"
                    style={{ backgroundColor: team.color }}
                  >
                    {team.logoUrl ? (
                      team.logoUrl.length > 5 ? <img src={team.logoUrl} className="w-full h-full object-cover" alt="Logo" /> : team.logoUrl
                    ) : (
                      team.name?.[0] || '?'
                    )}
                  </div>
                  <div className="absolute inset-0 flex flex-col gap-1 items-center justify-center bg-black/70 opacity-0 group-hover/logo:opacity-100 transition-opacity rounded-2xl">
                    <label className="text-[9px] font-black text-white uppercase cursor-pointer hover:text-blue-400">
                      Upload
                      <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && handleLogoUpload(team.id!, e.target.files[0])} />
                    </label>
                    <button 
                      onClick={() => setActivePickerTeamId(team.id!)}
                      className="text-[9px] font-black text-white uppercase hover:text-blue-400"
                    >
                      Emoji
                    </button>
                    <button 
                      onClick={() => setActiveGeneratorTeamId(team.id!)}
                      className="text-[9px] font-black text-emerald-400 uppercase hover:text-emerald-300"
                    >
                      IA
                    </button>
                  </div>
                </div>
                <div className="flex-1 overflow-hidden">
                  <input 
                    placeholder="Nome do Clube" 
                    value={team.name} 
                    onChange={e => updateTeam(team.id!, 'name', e.target.value)} 
                    className="bg-transparent text-xl font-black text-white outline-none w-full border-b border-transparent focus:border-blue-500 mb-1"
                  />
                  <div className="flex items-center justify-between">
                    <button onClick={() => saveTeamToVault(team)} className="text-[8px] font-black text-blue-400 uppercase tracking-widest hover:text-blue-300">Salvar no Cofre</button>
                  </div>
                </div>
              </div>

              {/* Seletor de Cores Moderno */}
              <div className="space-y-2">
                <label className="text-[8px] text-slate-500 font-black uppercase tracking-widest ml-1">Cor Principal</label>
                <div className="flex flex-wrap gap-2.5 p-3 bg-slate-800/50 rounded-2xl border border-slate-700/50">
                  {TEAM_COLORS.map((c) => (
                    <button
                      key={c}
                      onClick={() => updateTeam(team.id!, 'color', c)}
                      className={`w-7 h-7 rounded-full transition-all transform hover:scale-125 hover:z-10 relative ${
                        team.color === c ? 'ring-2 ring-white ring-offset-2 ring-offset-slate-900 shadow-lg scale-110' : 'opacity-80'
                      }`}
                      style={{ backgroundColor: c }}
                    >
                      {team.color === c && (
                        <span className="absolute inset-0 flex items-center justify-center text-[10px]">✓</span>
                      )}
                    </button>
                  ))}
                  <div className="relative w-7 h-7">
                    <input 
                      type="color" 
                      value={team.color} 
                      onChange={e => updateTeam(team.id!, 'color', e.target.value)} 
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
                    />
                    <div className="w-full h-full rounded-full border-2 border-dashed border-slate-600 flex items-center justify-center text-[10px] text-slate-500 pointer-events-none group-hover:border-blue-500">
                      +
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700/50">
                  <label className="text-[8px] text-slate-500 font-black uppercase mb-1 block">Técnico</label>
                  <input value={team.playerName} onChange={e => updateTeam(team.id!, 'playerName', e.target.value)} className="bg-transparent text-white font-bold w-full outline-none text-sm" />
                </div>
                <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700/50">
                  <label className="text-[8px] text-slate-500 font-black uppercase mb-1 block">Estádio</label>
                  <input value={team.stadium?.name} onChange={e => updateTeam(team.id!, 'stadium.name', e.target.value)} className="bg-transparent text-white font-bold w-full outline-none text-sm" />
                </div>
              </div>

              {savedTeams.length > 0 && (
                <div className="mt-2">
                  <select 
                    onChange={(e) => {
                      const saved = savedTeams.find(st => st.id === e.target.value);
                      if (saved) loadSavedTeam(team.id!, saved);
                    }}
                    className="w-full bg-slate-800 text-slate-400 text-[10px] font-bold p-2 rounded-lg border border-slate-700 outline-none"
                  >
                    <option value="">Carregar Time Salvo...</option>
                    {savedTeams.map(st => <option key={st.id} value={st.id}>{st.name}</option>)}
                  </select>
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="flex flex-col sm:flex-row gap-4 mt-12">
          <button onClick={onCancel} className="flex-1 py-6 bg-slate-700 hover:bg-slate-600 text-white font-black rounded-[2rem] uppercase tracking-widest transition-all text-sm">Voltar</button>
          <button onClick={handleStart} className="flex-[2] py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-[2rem] uppercase tracking-widest transition-all text-sm shadow-2xl shadow-blue-500/20">Iniciar Temporada</button>
        </div>
      </div>

      {activePickerTeamId && activeGenTeam && (
        <CrestPicker
          onClose={() => setActivePickerTeamId(null)}
          onSelect={(symbol) => updateTeam(activePickerTeamId, 'logoUrl', symbol)}
          teamColor={activeGenTeam.color || '#3b82f6'}
        />
      )}

      {activeGeneratorTeamId && activeGenTeam && (
        <AIImageGenerator
          onClose={() => setActiveGeneratorTeamId(null)}
          onImageGenerated={(base64) => updateTeam(activeGeneratorTeamId, 'logoUrl', base64)}
          defaultTeamName={activeGenTeam.name || ''}
          defaultColor={activeGenTeam.color || '#3b82f6'}
        />
      )}
    </div>
  );
};

export default SetupForm;

export interface Player {
  id: string;
  name: string;
  position: 'GOL' | 'DEF' | 'MEI' | 'ATA';
  rating: number;
  value: number;
}

export interface Stadium {
  name: string;
  primaryColor: string;
  capacity: number;
}

export interface Team {
  id: string;
  name: string;
  playerName: string;
  isHuman: boolean;
  color: string;
  logoUrl?: string;
  stadium: Stadium;
  players: Player[];
  budget: number;
  sponsorship: number;
  salaries: number;
}

export interface Match {
  id: string;
  homeId: string;
  awayId: string;
  homeScore: number | null;
  awayScore: number | null;
  round: number;
  stage: 'Fase de Grupos' | 'Oitavas' | 'Quartas' | 'Semifinal' | 'Final';
  leg?: 'Ida' | 'Volta';
}

export interface StandingRow {
  teamId: string;
  teamName: string;
  isHuman: boolean;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  gf: number;
  ga: number;
  gd: number;
  points: number;
  lastFive: ('W' | 'D' | 'L' | '-')[];
}

export type TournamentType = 'league' | 'cup';

export interface Championship {
  id: string;
  name: string;
  type: TournamentType;
  teams: Team[];
  matches: Match[];
  status: 'active' | 'finished';
  currentStage: 'group' | 'knockout';
  createdAt: number;
}

export type AppState = 'dashboard' | 'create' | 'active_tournament';
export type ActiveTab = 'table' | 'matches' | 'stadiums';

export interface SavedTeam {
  id: string;
  name: string;
  playerName: string;
  stadiumName: string;
  color: string;
  logoUrl?: string;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Team, Match, StandingRow, AppState, ActiveTab, Championship, TournamentType } from './types';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import ChampionModal from './components/ChampionModal';
import { syncChampionshipToCloud, fetchChampionshipsFromCloud, deleteChampionshipFromCloud } from './services/supabase';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('dashboard');
  const [championships, setChampionships] = useState<Championship[]>([]);
  const [activeChampId, setActiveChampId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ActiveTab>('table');
  const [showChampionModal, setShowChampionModal] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'error' | 'success'>('idle');

  const isFirstRender = useRef(true);

  useEffect(() => {
    const loadData = async () => {
      const saved = localStorage.getItem('manager_pro_v3_champs');
      if (saved) {
        try { setChampionships(JSON.parse(saved)); } catch (e) { console.error(e); }
      }
      const cloudData = await fetchChampionshipsFromCloud();
      if (cloudData && cloudData.length > 0) {
        const formattedCloud: Championship[] = cloudData.map(item => ({
          id: item.id,
          name: item.name,
          type: item.type as TournamentType,
          teams: item.teams,
          matches: item.matches,
          status: item.status as 'active' | 'finished',
          currentStage: (item.currentStage || 'group') as 'group' | 'knockout',
          createdAt: new Date(item.created_at || Date.now()).getTime()
        }));
        setChampionships(formattedCloud);
      }
    };
    loadData();
  }, []);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    localStorage.setItem('manager_pro_v3_champs', JSON.stringify(championships));
    if (championships.length > 0) {
      setSyncStatus('syncing');
      syncChampionshipToCloud(championships[0]).then(success => {
        setSyncStatus(success ? 'success' : 'error');
        setTimeout(() => setSyncStatus('idle'), 3000);
      });
    }
  }, [championships]);

  const activeChamp = useMemo(() => championships.find(c => c.id === activeChampId), [championships, activeChampId]);

  const generateLeagueSchedule = (teamList: Team[]) => {
    const n = teamList.length;
    const tempIds = teamList.map(t => t.id);
    const numTeams = tempIds.length;
    const numRoundsPerLeg = numTeams - 1;
    const firstLeg: Match[] = [];
    const rotation = [...tempIds];

    for (let r = 0; r < numRoundsPerLeg; r++) {
      for (let i = 0; i < numTeams / 2; i++) {
        const home = rotation[i];
        const away = rotation[numTeams - 1 - i];
        firstLeg.push({ id: `l1-${r}-${i}`, homeId: home, awayId: away, homeScore: null, awayScore: null, round: r + 1, stage: 'Fase de Grupos' });
      }
      rotation.splice(1, 0, rotation.pop()!);
    }
    const secondLeg = firstLeg.map(m => ({
      ...m, id: `l2-${m.id}`, homeId: m.awayId, awayId: m.homeId, round: m.round + numRoundsPerLeg
    }));
    return [...firstLeg, ...secondLeg];
  };

  const generateCupGroupStage = (teamList: Team[]) => {
    const n = teamList.length;
    const tempIds = teamList.map(t => t.id);
    const numRounds = n - 1;
    const groupMatches: Match[] = [];
    const rotation = [...tempIds];

    for (let r = 0; r < numRounds; r++) {
      for (let i = 0; i < n / 2; i++) {
        const home = rotation[i];
        const away = rotation[n - 1 - i];
        groupMatches.push({ id: `cup-g-${r}-${i}`, homeId: home, awayId: away, homeScore: null, awayScore: null, round: r + 1, stage: 'Fase de Grupos' });
      }
      rotation.splice(1, 0, rotation.pop()!);
    }
    return groupMatches;
  };

  const handleStartTournament = (name: string, type: TournamentType, teams: Team[]) => {
    const newChamp: Championship = {
      id: Math.random().toString(36).substr(2, 9),
      name, type, teams,
      matches: type === 'league' ? generateLeagueSchedule(teams) : generateCupGroupStage(teams),
      status: 'active',
      currentStage: 'group',
      createdAt: Date.now()
    };
    setChampionships([newChamp, ...championships]);
    setActiveChampId(newChamp.id);
    setAppState('active_tournament');
    setActiveTab('table');
  };

  const standings = useMemo(() => {
    if (!activeChamp) return [];
    // Tabela calculada apenas para jogos da Fase de Grupos
    const groupMatches = activeChamp.matches.filter(m => m.stage === 'Fase de Grupos');
    const stats: Record<string, StandingRow> = {};
    activeChamp.teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id, teamName: t.name, isHuman: t.isHuman,
        played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0, lastFive: []
      };
    });

    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    activeChamp.teams.forEach(t => resultsByTeam[t.id] = []);

    groupMatches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const h = stats[m.homeId];
        const a = stats[m.awayId];
        if (!h || !a) return;
        h.played++; a.played++;
        h.gf += m.homeScore; h.ga += m.awayScore;
        a.gf += m.awayScore; a.ga += m.homeScore;
        if (m.homeScore > m.awayScore) {
          h.won++; h.points += 3; a.lost++;
          resultsByTeam[m.homeId].push('W'); resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          a.won++; a.points += 3; h.lost++;
          resultsByTeam[m.homeId].push('L'); resultsByTeam[m.awayId].push('W');
        } else {
          h.drawn++; a.drawn++; h.points += 1; a.points += 1;
          resultsByTeam[m.homeId].push('D'); resultsByTeam[m.awayId].push('D');
        }
        h.gd = h.gf - h.ga; a.gd = a.gf - a.ga;
      }
    });

    return Object.values(stats)
      .map(s => ({ ...s, lastFive: resultsByTeam[s.teamId]?.slice(-5).reverse() || [] }))
      .sort((a, b) => b.points - a.points || b.won - a.won || b.gd - a.gd || b.gf - a.gf);
  }, [activeChamp]);

  const generateKnockout = (topTeams: StandingRow[], stageName: 'Semifinal' | 'Final') => {
    const knockoutMatches: Match[] = [];
    const maxRound = Math.max(0, ...activeChamp!.matches.map(m => m.round));

    if (stageName === 'Semifinal') {
      // 1º vs 4º, 2º vs 3º
      const pairs = [[topTeams[0], topTeams[3]], [topTeams[1], topTeams[2]]];
      pairs.forEach((pair, idx) => {
        knockoutMatches.push({ id: `semi-ida-${idx}`, homeId: pair[1].teamId, awayId: pair[0].teamId, homeScore: null, awayScore: null, round: maxRound + 1, stage: 'Semifinal', leg: 'Ida' });
        knockoutMatches.push({ id: `semi-volta-${idx}`, homeId: pair[0].teamId, awayId: pair[1].teamId, homeScore: null, awayScore: null, round: maxRound + 2, stage: 'Semifinal', leg: 'Volta' });
      });
    } else if (stageName === 'Final') {
      // Supõe-se que os vencedores das semis serão passados aqui (lógica simplificada para geração manual)
      knockoutMatches.push({ id: `final-ida`, homeId: topTeams[1].teamId, awayId: topTeams[0].teamId, homeScore: null, awayScore: null, round: maxRound + 1, stage: 'Final', leg: 'Ida' });
      knockoutMatches.push({ id: `final-volta`, homeId: topTeams[0].teamId, awayId: topTeams[1].teamId, homeScore: null, awayScore: null, round: maxRound + 2, stage: 'Final', leg: 'Volta' });
    }
    return knockoutMatches;
  };

  const advanceCup = () => {
    if (!activeChamp) return;
    const currentMatches = activeChamp.matches;
    const isGroupFinished = currentMatches.filter(m => m.stage === 'Fase de Grupos').every(m => m.homeScore !== null);

    if (isGroupFinished && activeChamp.currentStage === 'group') {
      const top4 = standings.slice(0, 4);
      const semis = generateKnockout(top4, 'Semifinal');
      setChampionships(prev => prev.map(c => c.id === activeChamp.id ? { ...c, matches: [...c.matches, ...semis], currentStage: 'knockout' } : c));
      setActiveTab('matches');
    } else if (activeChamp.currentStage === 'knockout') {
      const semis = activeChamp.matches.filter(m => m.stage === 'Semifinal');
      const isSemisFinished = semis.every(m => m.homeScore !== null);
      if (isSemisFinished && !activeChamp.matches.some(m => m.stage === 'Final')) {
        // Cálculo de vencedores das semis
        const finalists: any[] = [];
        const semiPairs = [0, 1];
        semiPairs.forEach(idx => {
          const ida = activeChamp.matches.find(m => m.id === `semi-ida-${idx}`)!;
          const volta = activeChamp.matches.find(m => m.id === `semi-volta-${idx}`)!;
          const totalHome = (ida.awayScore || 0) + (volta.homeScore || 0);
          const totalAway = (ida.homeScore || 0) + (volta.awayScore || 0);
          finalists.push({ teamId: totalHome >= totalAway ? volta.homeId : volta.awayId });
        });
        const finalMatches = generateKnockout(finalists as any, 'Final');
        setChampionships(prev => prev.map(c => c.id === activeChamp.id ? { ...c, matches: [...c.matches, ...finalMatches] } : c));
        setActiveTab('matches');
      }
    }
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setChampionships(prev => prev.map(c => {
      if (c.id === activeChampId) {
        return {
          ...c,
          matches: c.matches.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m)
        };
      }
      return c;
    }));
  };

  const deleteChampionship = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Excluir campeonato?")) {
      setChampionships(prev => prev.filter(c => c.id !== id));
      await deleteChampionshipFromCloud(id);
      if (activeChampId === id) setAppState('dashboard');
    }
  };

  const currentChampion = useMemo(() => {
    if (!activeChamp) return undefined;
    if (activeChamp.type === 'league') return standings[0];

    const finalMatches = activeChamp.matches.filter(m => m.stage === 'Final');
    if (finalMatches.length === 2 && finalMatches.every(m => m.homeScore !== null)) {
      const ida = finalMatches.find(m => m.leg === 'Ida')!;
      const volta = finalMatches.find(m => m.leg === 'Volta')!;
      const totalHome = (ida.awayScore || 0) + (volta.homeScore || 0);
      const totalAway = (ida.homeScore || 0) + (volta.awayScore || 0);
      const winnerId = totalHome >= totalAway ? volta.homeId : volta.awayId;
      return standings.find(s => s.teamId === winnerId);
    }
    return undefined;
  }, [activeChamp, standings]);

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setAppState('dashboard')}>
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
              <span className="text-white font-black text-xl">⚽</span>
            </div>
            <div>
              <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block uppercase leading-none">Super League</h1>
              <div className="flex items-center gap-1.5 mt-1">
                <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'syncing' ? 'bg-amber-500 animate-pulse' : syncStatus === 'error' ? 'bg-rose-500' : 'bg-emerald-500'}`}></span>
                <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{syncStatus === 'syncing' ? 'Sync...' : 'Cloud'}</span>
              </div>
            </div>
          </div>
          {appState === 'active_tournament' && activeChamp && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700 gap-1">
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}
          <div className="flex gap-2">
            {appState !== 'dashboard' && <button onClick={() => setAppState('dashboard')} className="px-4 py-2 bg-slate-800 text-slate-300 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-700 border border-slate-700">Painel</button>}
            <button onClick={() => setAppState('create')} className="px-4 py-2 bg-blue-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-500 shadow-lg">+ Novo</button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'dashboard' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-top-4 duration-700">
            <div className="text-center">
              <h2 className="text-5xl md:text-7xl font-black text-white tracking-tighter uppercase italic leading-none">Meus <span className="text-blue-500">Torneios</span></h2>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {championships.map(c => (
                <div key={c.id} onClick={() => { setActiveChampId(c.id); setAppState('active_tournament'); setActiveTab('table'); }} className="bg-slate-800/80 border border-slate-700 p-8 rounded-[2.5rem] shadow-xl hover:border-blue-500/40 transition-all group relative overflow-hidden cursor-pointer flex flex-col h-full">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 group-hover:bg-blue-600/10"></div>
                  <div className="relative z-10 flex flex-col h-full">
                    <div className="flex justify-between items-start mb-6">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${c.type === 'league' ? 'bg-blue-500/20 text-blue-400' : 'bg-amber-500/20 text-amber-400'}`}>{c.type === 'league' ? 'Liga' : 'Copa'}</span>
                      <button onClick={(e) => deleteChampionship(e, c.id)} className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-900/50 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 transition-all z-20">✕</button>
                    </div>
                    <h3 className="text-3xl font-black text-white mb-2 uppercase tracking-tighter truncate group-hover:text-blue-400">{c.name}</h3>
                    <div className="mt-auto flex items-center justify-between pt-4 border-t border-slate-700/50">
                      <span className="text-[10px] text-slate-600 font-bold uppercase tracking-widest">{new Date(c.createdAt).toLocaleDateString()}</span>
                      <span className="text-blue-500 font-black text-xs uppercase group-hover:translate-x-1 transition-transform">Gerenciar →</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === 'create' && <SetupForm onCancel={() => setAppState('dashboard')} onStart={handleStartTournament} />}

        {appState === 'active_tournament' && activeChamp && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex justify-between items-end">
              <div>
                <p className="text-slate-500 font-black text-[10px] uppercase tracking-[0.3em]">{activeChamp.type === 'league' ? 'PONTOS CORRIDOS' : 'COPA COM GRUPOS'}</p>
                <h2 className="text-4xl md:text-5xl font-black text-white uppercase tracking-tighter italic">{activeChamp.name}</h2>
              </div>
              {activeChamp.type === 'cup' && (
                <button 
                  onClick={advanceCup}
                  className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl transition-all"
                >
                  {activeChamp.currentStage === 'group' ? 'Gerar Mata-Mata' : 'Gerar Próxima Fase'}
                </button>
              )}
            </div>
            {activeTab === 'table' && <LeagueTable standings={standings} teams={activeChamp.teams} />}
            {activeTab === 'matches' && (
              <MatchList 
                matches={activeChamp.matches} 
                teams={activeChamp.teams} 
                onUpdateScore={updateScore} 
                onShowResults={() => setShowChampionModal(true)}
                tournamentType={activeChamp.type}
              />
            )}
          </div>
        )}
      </main>

      {showChampionModal && activeChamp && (
        <ChampionModal 
          champion={currentChampion} 
          teamDetails={activeChamp.teams.find(t => t.id === currentChampion?.teamId)} 
          onClose={() => setShowChampionModal(false)}
          type={activeChamp.type}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Match, Team, TournamentType } from '../types';

interface Props {
  matches: Match[];
  teams: Team[];
  onUpdateScore: (matchId: string, homeScore: number, awayScore: number) => void;
  onShowResults: () => void;
  tournamentType?: TournamentType;
}

const MatchList: React.FC<Props> = ({ matches, teams, onUpdateScore, onShowResults, tournamentType }) => {
  const [selectedRound, setSelectedRound] = useState(1);
  const totalRounds = Math.max(...matches.map(m => m.round), 1);
  const filteredMatches = matches.filter(m => m.round === selectedRound);
  const isLastRound = selectedRound === totalRounds;

  const getTeam = (id: string) => teams.find(t => t.id === id);
  const allPlayedTotal = matches.every(m => m.homeScore !== null && m.awayScore !== null);

  const getRoundLabel = (round: number) => {
    const match = matches.find(m => m.round === round);
    if (tournamentType === 'cup' && match) {
      if (match.stage === 'Fase de Grupos') return `Grupo - R${round}`;
      return `${match.stage} (${match.leg})`;
    }
    return `Rodada ${round}`;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center bg-slate-800/50 p-4 rounded-3xl border border-slate-700 overflow-x-auto custom-scrollbar gap-4">
        <div className="flex gap-2">
          {Array.from({ length: totalRounds }, (_, i) => i + 1).map(round => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              className={`px-4 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all min-w-[140px] border ${
                selectedRound === round 
                  ? 'bg-blue-600 text-white border-blue-500 shadow-xl' 
                  : 'bg-slate-900/50 text-slate-500 border-slate-700 hover:text-white'
              }`}
            >
              {getRoundLabel(round)}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {filteredMatches.map(match => {
          const home = getTeam(match.homeId);
          const away = getTeam(match.awayId);
          if (!home || !away) return null;

          return (
            <div key={match.id} className="bg-slate-800/80 rounded-[2.5rem] p-8 border border-slate-700 shadow-2xl group hover:border-blue-500/30 transition-all flex flex-col items-center">
              <div className="text-[9px] text-blue-500 font-black uppercase tracking-[0.3em] mb-6 border border-blue-500/20 px-4 py-1 rounded-full bg-blue-500/5">
                {match.stage} {match.leg ? `- ${match.leg}` : ''}
              </div>
              <div className="flex items-center justify-between gap-6 w-full">
                <div className="flex-1 flex flex-col items-center gap-4">
                  <div className="w-20 h-20 rounded-[1.5rem] flex items-center justify-center text-3xl font-black text-white shadow-xl border-2 border-slate-700 overflow-hidden" style={{ backgroundColor: home.color }}>
                    {home.logoUrl ? <img src={home.logoUrl} className="w-full h-full object-cover p-1" /> : home.name[0]}
                  </div>
                  <span className="text-sm font-black text-white text-center uppercase truncate w-full">{home.name}</span>
                </div>
                <div className="flex items-center gap-4">
                  <input type="number" min="0" placeholder="0" value={match.homeScore === null ? '' : match.homeScore} onChange={(e) => onUpdateScore(match.id, parseInt(e.target.value) || 0, match.awayScore || 0)} className="w-16 h-16 bg-slate-900 border-2 border-slate-700 rounded-2xl text-center text-2xl font-black text-white focus:border-blue-500 outline-none" />
                  <span className="text-slate-600 font-black text-xl">x</span>
                  <input type="number" min="0" placeholder="0" value={match.awayScore === null ? '' : match.awayScore} onChange={(e) => onUpdateScore(match.id, match.homeScore || 0, parseInt(e.target.value) || 0)} className="w-16 h-16 bg-slate-900 border-2 border-slate-700 rounded-2xl text-center text-2xl font-black text-white focus:border-blue-500 outline-none" />
                </div>
                <div className="flex-1 flex flex-col items-center gap-4">
                  <div className="w-20 h-20 rounded-[1.5rem] flex items-center justify-center text-3xl font-black text-white shadow-xl border-2 border-slate-700 overflow-hidden" style={{ backgroundColor: away.color }}>
                    {away.logoUrl ? <img src={away.logoUrl} className="w-full h-full object-cover p-1" /> : away.name[0]}
                  </div>
                  <span className="text-sm font-black text-white text-center uppercase truncate w-full">{away.name}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {isLastRound && allPlayedTotal && (
        <div className="pt-12 flex justify-center animate-in fade-in slide-in-from-bottom-6 duration-700">
          <button onClick={onShowResults} className="px-16 py-6 bg-gradient-to-r from-amber-500 to-orange-600 text-white font-black rounded-3xl uppercase tracking-[0.2em] shadow-2xl hover:scale-105 active:scale-95 transition-all text-sm flex items-center gap-4">
            Coroar Grande Campeão 🏆
          </button>
        </div>
      )}
    </div>
  );
};

